define(["core/ajax","core/notification"],function(Ajax,Notification){const pauseOtherVideos=current=>{document.querySelectorAll(".videoforum-video").forEach(video=>{video!==current&&!video.paused&&video.pause()})};const track=(cmid,video,ended)=>{const postid=Number(video.dataset.postid||0);postid&&Ajax.call([{methodname:"mod_videoforum_track_view",args:{cmid:cmid,postid:postid,position:Number(video.currentTime||0),ended:Boolean(ended)}}])[0].catch(Notification.exception)};const moderate=(cmid,button)=>{const action=button.dataset.moderation,postid=Number(button.dataset.postid||0);if("delete"===action&&!window.confirm(button.textContent.trim()+"?"))return;button.disabled=!0,Ajax.call([{methodname:"mod_videoforum_moderate_post",args:{cmid:cmid,postid:postid,action:action}}])[0].then(()=>window.location.reload()).catch(error=>{button.disabled=!1,Notification.exception(error)})};const report=(cmid,button)=>{const postid=Number(button.dataset.postid||0),details=window.prompt(button.textContent.trim());null!==details&&(button.disabled=!0,Ajax.call([{methodname:"mod_videoforum_report_post",args:{cmid:cmid,postid:postid,reason:"other",details:details}}])[0].then(()=>{button.disabled=!0}).catch(error=>{button.disabled=!1,Notification.exception(error)}))};return{init:config=>{const cmid=Number(config.cmid||0);cmid&&(document.querySelectorAll(".videoforum-video").forEach(video=>{video.addEventListener("play",()=>pauseOtherVideos(video)),video.addEventListener("pause",()=>{!video.ended&&video.currentTime>0&&track(cmid,video,!1)}),video.addEventListener("ended",()=>track(cmid,video,!0))}),document.addEventListener("click",event=>{const button=event.target.closest("[data-action]");button&&("moderate"===button.dataset.action?moderate(cmid,button):"report"===button.dataset.action&&report(cmid,button))}))}}});